using System;using System.Collections.Generic;using System.Diagnostics;using System.IO;using System.Linq;using System.Net;using System.Net.Sockets;using System.Reflection;using System.Threading;
namespace SshScreen {
public static class RouteFlowLinkChecks {
 const BindingFlags F=BindingFlags.NonPublic|BindingFlags.Instance;
 static double Now(){return Stopwatch.GetTimestamp()*1000.0/Stopwatch.Frequency;}
 static void Set(object o,string field,object value){typeof(ControllerForm).GetField(field,F).SetValue(o,value);}
 static void Observe(ControllerForm form,long sequence,int x){var data=Wire.Map("sequence",sequence,"window",42L,"found",true,"position_fresh",true,"body",new[]{300,200},"direction","right","direction_fresh",true,"capture_age_ms",0.0,"minimap_dot",new[]{x,40},"monsters",new object[0]);var gate=typeof(ControllerForm).GetField("observationGate",F).GetValue(form);lock(gate){Set(form,"observation",data);Set(form,"observationAt",Now());}}
 [STAThread]public static void Main(string[] args){string root=args[0];var report=Wire.Map("ok",false,"game_input",false,"ssh_started",false,"transport","loopback fake input receiver");var server=new TcpListener(IPAddress.Loopback,0);server.Start();var gate=new object();var events=new List<Dictionary<string,object>>();var held=new HashSet<int>();var moving=new ManualResetEvent(false);var jumping=new ManualResetEvent(false);var released=new ManualResetEvent(false);ControllerForm form=null;Link link=null;Thread worker=null;Exception workerError=null;try{
  new Thread(()=>{try{using(var c=server.AcceptTcpClient())using(var stream=c.GetStream()){while(true){var request=Wire.Receive(stream).Header;string op=Wire.Str(request,"op");int key=Wire.Int(request,"vk");lock(gate){if(op=="key_down"){held.Add(key);if(key==39)moving.Set();if(key==18)jumping.Set();}else if(op=="key_up")held.Remove(key);else if(op=="release"){held.Clear();released.Set();}events.Add(Wire.Map("op",op,"key",key,"time",Now()));}Wire.Send(stream,Wire.Map("ok",true));}}}catch{}}){IsBackground=true}.Start();
  var role=new RolePreset();role.battle.mode="route";role.battle.detectMonsters=false;var route=new RouteDocument();route.nodes.AddRange(new[]{new RouteNode{id="A",x=0,y=40},new RouteNode{id="B",x=20,y=40},new RouteNode{id="C",x=40,y=20}});route.edges.AddRange(new[]{new RouteEdge{id="walk",from="A",to="B",kind="walk",both=true,duration=1000},new RouteEdge{id="jump",from="B",to="C",kind="jump",jumpHold=80,duration=600}});
  form=new ControllerForm(root,false,false);var handle=form.Handle;Set(form,"running",true);Set(form,"generation",1);Set(form,"autoEpoch",7);Set(form,"autoRunning",true);Set(form,"autoWindow",42L);Set(form,"target",42L);Set(form,"planner",new CombatPlanner(role,Now(),route));Observe(form,1,0);
  link=new Link(((IPEndPoint)server.LocalEndpoint).Port,"offline-test-only","control");var method=typeof(ControllerForm).GetMethod("ControlWorker",F);worker=new Thread(()=>{try{method.Invoke(form,new object[]{1,link});}catch(Exception e){workerError=e.GetBaseException();}}){IsBackground=true};worker.Start();if(!moving.WaitOne(2500))throw new IOException("Worker did not begin route walking");
  Thread.Sleep(70);Observe(form,2,6);Thread.Sleep(70);Observe(form,3,12);Thread.Sleep(70);double arrived=Now();Observe(form,4,19);if(!jumping.WaitOne(1500))throw new IOException("Worker did not join the takeoff");
  lock(gate){int hop=events.FindIndex(x=>Wire.Str(x,"op")=="key_down"&&Wire.Int(x,"key")==18);var prefix=events.Take(hop+1).ToList();if(prefix.Count(x=>Wire.Str(x,"op")=="key_down"&&Wire.Int(x,"key")==39)!=1||prefix.Any(x=>Wire.Str(x,"op")=="key_up"&&Wire.Int(x,"key")==39))throw new IOException("Actual worker released direction before the jump");report["arrival_to_jump_ms"]=Convert.ToDouble(events[hop]["time"])-arrived;report["continuous_direction_through_takeoff"]=true;}
  typeof(ControllerForm).GetMethod("Pause",F).Invoke(form,null);if(!released.WaitOne(2000))throw new IOException("Pause did not release continued route input");Thread.Sleep(300);
  lock(gate){int release=events.FindIndex(x=>Wire.Str(x,"op")=="release");if(held.Count!=0||events.Skip(release+1).Any(x=>Wire.Str(x,"op")=="key_down"))throw new IOException("Route input survived pause");report["held_after_pause"]=held.Count;report["pause_cancels_continued_direction_and_jump"]=true;report["events"]=events;}
  report["ok"]=true;
 }catch(Exception e){report["error"]=e.GetBaseException().Message;Environment.ExitCode=1;}finally{if(form!=null){Set(form,"running",false);if(worker!=null)worker.Join(2000);form.Dispose();}if(link!=null)link.Dispose();server.Stop();if(workerError!=null){report["ok"]=false;report["worker_error"]=workerError.Message;Environment.ExitCode=1;}Wire.Save(Path.Combine(root,"route-flow-link-checks.json"),report);Console.WriteLine(new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(report));}}
}}
